joint = {
    (1, 'Low'): 0.25, (1, 'High'): 0.05,
    (2, 'Low'): 0.20, (2, 'High'): 0.20,
    (3, 'Low'): 0.05, (3, 'High'): 0.25,
}
xs = [1, 2, 3]
marginal_x = {x: sum(p for (a, b), p in joint.items() if a == x) for x in xs}
print({x: round(p, 2) for x, p in marginal_x.items()})   # {1: 0.3, 2: 0.4, 3: 0.3}

joint = {
